import jsPDF from 'jspdf';

// Logo AAFCorsan com bordas arredondadas
const LOGO_BASE64 = 'data:image/jpeg;base64,';

interface PDFHeaderOptions {
  doc: jsPDF;
  title: string;
  totalRecords?: number;
  startY?: number;
  logoWidth?: number;
  logoHeight?: number;
}

/**
 * Adiciona cabeçalho padrão aos PDFs com título à esquerda e logo à direita.
 * Retorna a posição Y após o cabeçalho (para iniciar a tabela).
 */
export const addPDFHeader = ({
  doc,
  title,
  totalRecords,
  startY = 10,
  logoWidth = 15,
  logoHeight = 15,
}: PDFHeaderOptions): number => {
  const pageWidth = doc.internal.pageSize.getWidth();
  const margin = 14;

  // Título à esquerda
  const titleY = startY + 6;
  doc.setFontSize(16);
  doc.setFont('helvetica', 'bold');
  doc.text(title, margin, titleY);

  // Logo à direita com bordas arredondadas
  try {
    const logoX = pageWidth - margin - logoWidth;
    doc.addImage(LOGO_BASE64, 'JPEG', logoX, startY, logoWidth, logoHeight);
  } catch (e) {
    console.warn('[PDF] Erro ao adicionar logo:', e);
  }

  // Linha separadora abaixo do cabeçalho
  const currentY = startY + logoHeight + 4;
  doc.setDrawColor(200, 200, 200);
  doc.setLineWidth(0.3);
  doc.line(margin, currentY, pageWidth - margin, currentY);

  return currentY + 6;
};

/**
 * Adiciona rodapé com data de geração, total de registros e número de páginas.
 */
export const addPDFFooter = (doc: jsPDF, totalRecords?: number) => {
  const totalPages = doc.getNumberOfPages();
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const margin = 14;
  const now = new Date().toLocaleString('pt-BR');

  for (let i = 1; i <= totalPages; i++) {
    doc.setPage(i);
    
    // Linha separadora do rodapé
    doc.setDrawColor(200, 200, 200);
    doc.setLineWidth(0.3);
    doc.line(margin, pageHeight - 12, pageWidth - margin, pageHeight - 12);
    
    // Data de geração à esquerda
    doc.setFontSize(7);
    doc.setFont('helvetica', 'normal');
    doc.text(`Gerado em: ${now}${totalRecords !== undefined ? ` | Total: ${totalRecords} registros` : ''}`, margin, pageHeight - 8);
    
    // Número da página à direita
    doc.text(`Página ${i} de ${totalPages}`, pageWidth - margin, pageHeight - 8, { align: 'right' });
  }
};
